package cn.xiaoyanjiu.ff14chat.trial;
import android.app.Activity;import android.graphics.*;import android.webkit.*;import android.view.*;import android.widget.*;import org.json.JSONObject;
/** Whole app shell, not a separately sized title bar. The remote site fills only its content slot. */
final class BrowserToolbar {
 static final java.util.WeakHashMap<Activity,Shell> views=new java.util.WeakHashMap<>();
 static final class Shell {WebView frame;Content site;volatile String hint="";float[] bounds;Runnable home;}
 static final class Content extends WebView {float radius;final Path clip=new Path();Content(Activity a){super(new android.content.MutableContextWrapper(a));}@Override public void draw(Canvas c){if(radius<=0){super.draw(c);return;}int saved=c.save();clip.reset();// WebView draw coordinates include its scroll offset; keep the clip on the visible viewport.
float x=getScrollX(),y=getScrollY();clip.addRoundRect(new RectF(x,y,x+getWidth(),y+getHeight()),new float[]{0,0,0,0,radius,radius,radius,radius},Path.Direction.CW);c.clipPath(clip);super.draw(c);c.restoreToCount(saved);}}
 static String theme(Activity a){try{String value=new JSONObject(a.getSharedPreferences("appearance",0).getString("settings","{}")).optString("theme","game");return java.util.Arrays.asList("game","black","white","yellow","grey").contains(value)?value:"game";}catch(Exception e){return "game";}}
 static void refresh(Activity a){Shell s=views.get(a);if(s==null||a.isDestroyed())return;String theme=theme(a);boolean light=theme.equals("white")||theme.equals("yellow")||theme.equals("grey");int color=Color.parseColor(theme.equals("white")?"#f6f7fb":theme.equals("yellow")?"#f6e8bd":theme.equals("grey")?"#e2e5e9":theme.equals("game")?"#313031":"#15181f");a.getWindow().getDecorView().setBackgroundColor(color);if(s.frame.getParent() instanceof View)((View)s.frame.getParent()).setBackgroundColor(color);a.getWindow().setStatusBarColor(color);a.getWindow().setNavigationBarColor(color);if(android.os.Build.VERSION.SDK_INT>=30){android.view.WindowInsetsController c=a.getWindow().getInsetsController();if(c!=null)c.setSystemBarsAppearance(light?24:0,24);}else a.getWindow().getDecorView().setSystemUiVisibility(light?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);s.frame.evaluateJavascript("document.body.dataset.theme="+JSONObject.quote(theme),null);}
 static void close(Activity a){Shell s=views.remove(a);if(s!=null){s.frame.removeJavascriptInterface("Header");s.frame.destroy();}}
 static void home(Activity a,Runnable action){Shell s=views.get(a);if(s!=null)s.home=action;}
 static TextView hintSink(Activity a){return new TextView(a){@Override protected void onTextChanged(CharSequence text,int start,int before,int count){Shell s=views.get(a);if(s!=null)s.hint=text==null?"":text.toString();}};}
 static void attach(Activity a,FrameLayout root,Content site){Shell s=views.get(a);if(s.site!=null&&s.site!=site)s.site.setVisibility(View.INVISIBLE);s.site=site;site.setVisibility(View.INVISIBLE);if(site.getParent()==null)root.addView(site,new FrameLayout.LayoutParams(1,1));root.bringChildToFront(site);layout(s);}
 static void layout(Shell s){if(s.site==null||s.bounds==null||s.frame.getWidth()<1)return;float[] b=s.bounds;float scale=s.frame.getWidth()/b[4];int left=Math.round(b[0]*scale),top=Math.round(b[1]*scale),right=Math.round((b[0]+b[2])*scale),bottom=Math.round((b[1]+b[3])*scale);if(right<=left||bottom<=top){s.site.setVisibility(View.INVISIBLE);return;}FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(right-left,bottom-top);p.leftMargin=left;p.topMargin=top;ViewGroup.LayoutParams old=s.site.getLayoutParams();if(!(old instanceof FrameLayout.LayoutParams)||old.width!=p.width||old.height!=p.height||((FrameLayout.LayoutParams)old).leftMargin!=left||((FrameLayout.LayoutParams)old).topMargin!=top)s.site.setLayoutParams(p);s.site.radius=b[5]*scale;s.site.setVisibility(View.VISIBLE);s.site.invalidate();}
 static WebView create(Activity a,String route,String title,Runnable back,Runnable refresh,String extra,Runnable extraAction){return create(a,route,title,back,refresh,extra,extraAction,"",()->{});}
 static WebView create(Activity a,String route,String title,Runnable back,Runnable refresh,String extra,Runnable extraAction,String secondary,Runnable secondaryAction){Shell s=new Shell();WebView w=new WebView(a);s.frame=w;views.put(a,s);w.setBackgroundColor(Color.TRANSPARENT);w.getSettings().setJavaScriptEnabled(true);w.getSettings().setTextZoom(100);w.getSettings().setAllowFileAccess(false);w.getSettings().setAllowContentAccess(false);w.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onPageFinished(WebView v,String url){refresh(a);}});
  w.addJavascriptInterface(new Object(){@JavascriptInterface public String state(){return ChatService.state.split(" · ")[0];}@JavascriptInterface public String hint(){return s.hint;}@JavascriptInterface public void action(String name){a.runOnUiThread(()->{if(a.isDestroyed())return;switch(name){case "menu":BrowserDrawer.show(a,route);break;case "back":back.run();break;case "refresh":refresh.run();break;case "home":if(s.home!=null)s.home.run();break;case "extra":extraAction.run();break;case "secondary":secondaryAction.run();break;case "hint":if(route.equals("fishing"))extraAction.run();break;}});}@JavascriptInterface public void content(float x,float y,float width,float height,float viewport,float radius){if(!Float.isFinite(x)||!Float.isFinite(y)||!Float.isFinite(width)||!Float.isFinite(height)||!Float.isFinite(viewport)||!Float.isFinite(radius)||x<0||y<0||width<0||height<0||viewport<=0||radius<0)return;a.runOnUiThread(()->{if(a.isDestroyed()||views.get(a)!=s)return;s.bounds=new float[]{x,y,width,height,viewport,radius};layout(s);});}},"Header");
  try{String index=BrowserDrawer.asset(a,"index.html");int begin=index.indexOf("<style>")+7,end=index.indexOf("</style>",begin);String theme=theme(a);String html=BrowserDrawer.asset(a,"browser-header.html").replace("__APP_STYLE__",index.substring(begin,end)).replace("__THEME__",theme).replace("__TITLE_JSON__",JSONObject.quote(title)).replace("__EXTRA_JSON__",JSONObject.quote(extra)).replace("__SECONDARY_JSON__",JSONObject.quote(secondary));w.loadDataWithBaseURL("file:///android_asset/",html,"text/html","UTF-8",null);}catch(Exception e){Toast.makeText(a,"窗口加载失败："+e.getMessage(),Toast.LENGTH_SHORT).show();}return w;
 }
}
